'use client';

import { useState, useEffect } from 'react';
import { useQuery } from '@tanstack/react-query';

const useVisibilityPolling = (
  queryKey: unknown[]
) => {
  const [isVisible, setIsVisible] = useState(true);

  useEffect(() => {
    const handleVisibilityChange = () => {
      setIsVisible(document.visibilityState === 'visible');
    };

    document.addEventListener('visibilitychange', handleVisibilityChange);
    return () => {
      document.removeEventListener('visibilitychange', handleVisibilityChange);
    };
  }, []);

  return useQuery({
    queryKey,
    queryFn: fetchNotifications,
    enabled: isVisible,
    refetchInterval: isVisible ? 5000 : false
  });
};

const LiveDashboard = () => {
  const [isLive, setIsLive] = useState(true);

  const { data: metrics } = useQuery({
    queryKey: ['metrics'],
    queryFn: fetchMetrics,
    refetchInterval: isLive ? 2000 : false,
    enabled: true
  });

  return (
    <div>
      <button onClick={() => setIsLive(!isLive)}>
        {isLive ? 'Pause Live Updates' : 'Resume Live Updates'}
      </button>
      <MetricsDisplay data={metrics} />
    </div>
  );
};

'use client';

import { useEffect } from 'react';
import { useQuery, useQueryClient } from '@tanstack/react-query';

type TickerData = {
  price: number;
  change: number;
  lastUpdated: string;
};

const useWebSocketTicker = (symbol: string) => {
  const queryClient = useQueryClient();

  useEffect(() => {
    const ws = new WebSocket(`wss://stream.example.com/${symbol}`);

    ws.onmessage = (event) => {
      const tick = JSON.parse(event.data) as TickerData;

      queryClient.setQueryData(['ticker', symbol], (old: TickerData | undefined) => ({
        ...old,
        price: tick.price,
        change: tick.change,
        lastUpdated: new Date().toISOString()
      }));
    };

    ws.onclose = () => {
      console.log('WebSocket disconnected');
    };

    return () => ws.close();
  }, [symbol, queryClient]);

  return useQuery({
    queryKey: ['ticker', symbol],
    queryFn: () => fetchTicker(symbol),
    staleTime: Infinity
  });
};
